<?php
// Admin dashboard and store overview.

    $customers=(int)one('SELECT COUNT(*) AS n FROM tb_user')['n']; $products=(int)one('SELECT COUNT(*) AS n FROM tb_barang')['n']; $orders=(int)one('SELECT COUNT(*) AS n FROM orders')['n'];
    $revenue=(float)(one("SELECT SUM(d.harga_satuan*d.qty) AS n FROM details d JOIN orders o ON o.id_orders=d.id_orders WHERE o.status IN ('Selesai','Selesai Belum Dinilai')")['n']??0);
    $pending=(int)one("SELECT COUNT(*) AS n FROM orders WHERE status='Menunggu Konfirmasi'")['n'];
    $recent=query('SELECT o.*,u.nama,(SELECT SUM(d.harga_satuan*d.qty) FROM details d WHERE d.id_orders=o.id_orders) AS total FROM orders o JOIN tb_user u ON u.id_user=o.id_user ORDER BY o.id_orders DESC LIMIT 6');
    $low=query('SELECT * FROM tb_barang WHERE stok<=3 ORDER BY stok,id_barang DESC LIMIT 5');
    $chart=query("SELECT DATE_FORMAT(o.tanggal,'%Y-%m') AS bulan,SUM(d.harga_satuan*d.qty) AS total FROM orders o JOIN details d ON d.id_orders=o.id_orders WHERE o.status IN ('Selesai','Selesai Belum Dinilai') GROUP BY DATE_FORMAT(o.tanggal,'%Y-%m') ORDER BY bulan DESC LIMIT 6"); $chart=array_reverse($chart); $max=max(1,...array_column($chart,'total'));
    ?>
    <section class="admin-welcome"><div><span class="eyebrow">SELAMAT DATANG KEMBALI</span><h2>Semua aktivitas toko,<br>dalam satu tempat.</h2><p><?= $pending ?> pembayaran menunggu konfirmasi Anda.</p></div><a class="button light" href="<?= e(url('bangjanganbang/konfirmasi.php')) ?>">Periksa pesanan <?= icon('arrow') ?></a></section><div class="stats-grid"><?php foreach([['Total pemasukan',rupiah($revenue),'chart','Dari pesanan selesai'],['Pesanan',$orders,'bag','Seluruh riwayat pesanan'],['Produk aktif',$products,'box','Terdaftar di katalog'],['Pelanggan',$customers,'user','Akun terdaftar']] as [$label,$value,$glyph,$desc]): ?><article class="stat-card"><div><span><?= e($label) ?></span><?= icon($glyph) ?></div><strong><?= e($value) ?></strong><small><?= e($desc) ?></small></article><?php endforeach; ?></div><div class="dashboard-grid"><section class="panel"><div class="section-title"><div><h2>Pemasukan bulanan</h2><p class="muted small-text">Enam bulan terakhir yang memiliki transaksi selesai</p></div><?= icon('chart') ?></div><?php if(!$chart): ?><p class="muted">Belum ada transaksi selesai.</p><?php else: ?><div class="bar-chart" role="img" aria-label="Pemasukan bulanan"><?php foreach($chart as $point): ?><div class="bar-column"><small><?= rupiah($point['total']) ?></small><div class="bar-track"><div class="bar" style="height:<?= max(2,round($point['total']/$max*100)) ?>%"></div></div><span><?= e($point['bulan']) ?></span></div><?php endforeach; ?></div><?php endif; ?></section><section class="panel"><div class="section-title"><h2>Perlu perhatian</h2><span class="badge pending">Stok menipis</span></div><?php if(!$low): ?><p class="muted">Stok semua produk mencukupi.</p><?php endif; foreach($low as $item): ?><a class="low-stock-item" href="<?= e(url('bangjanganbang/add_product.php?id='.$item['id_barang'].'&mode=stock')) ?>"><img src="<?= e(url($item['img'])) ?>" alt=""><span><?= e($item['nama_barang']) ?><small><?= (int)$item['stok'] ?> unit tersisa</small></span><?= icon('arrow') ?></a><?php endforeach; ?></section></div><section class="panel section"><div class="section-title"><h2>Pesanan terbaru</h2><a class="text-link" href="<?= e(url('bangjanganbang/konfirmasi.php')) ?>">Kelola pesanan <?= icon('arrow') ?></a></div><div class="table-scroll"><table><thead><tr><th>Pesanan</th><th>Pelanggan</th><th>Tanggal</th><th>Subtotal produk</th><th>Status</th></tr></thead><tbody><?php foreach($recent as $item): ?><tr><td><strong>#TM-<?= (int)$item['id_orders'] ?></strong></td><td><?= e($item['nama']) ?></td><td><?= e(date('d M Y',strtotime($item['tanggal']))) ?></td><td><?= rupiah($item['total']) ?></td><td><?= status_badge($item['status']) ?></td></tr><?php endforeach; if(!$recent): ?><tr><td colspan="5" class="muted">Belum ada pesanan.</td></tr><?php endif; ?></tbody></table></div></section>
    <?php
